-- Generated metadata stays current even when an older writer edits these rows.
-- This avoids repeating Unicode normalization while scanning public candidates.
ALTER TABLE np_posts
    ADD COLUMN public_search_title text GENERATED ALWAYS AS (np_public_search_normalize_v1(title)) STORED,
    ADD COLUMN public_search_excerpt text GENERATED ALWAYS AS (np_public_search_normalize_v1(excerpt)) STORED,
    ADD COLUMN public_search_author text GENERATED ALWAYS AS (np_public_search_normalize_v1(COALESCE(NULLIF(metadata->>'author_name',''),'NewPress'))) STORED;
ALTER TABLE np_users ADD COLUMN public_search_name text GENERATED ALWAYS AS (np_public_search_normalize_v1(display_name)) STORED;
ALTER TABLE np_terms ADD COLUMN public_search_name text GENERATED ALWAYS AS (np_public_search_normalize_v1(name)) STORED;

CREATE FUNCTION np_invalidate_public_search_body() RETURNS trigger
LANGUAGE plpgsql AS $invalidate$
BEGIN
    NEW.public_search_body := NULL;
    RETURN NEW;
END
$invalidate$;

CREATE TRIGGER np_posts_invalidate_public_search_body
BEFORE UPDATE ON np_posts FOR EACH ROW
WHEN (OLD.content_html IS DISTINCT FROM NEW.content_html)
EXECUTE FUNCTION np_invalidate_public_search_body();
